-- Removes only deterministic Candidate review fixtures. Candidate-only.
BEGIN;
DO $guard$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM review_private.environment_guard
    WHERE singleton AND project_ref='fssogssryeunkjkdgewx' AND purpose='CANDIDATE_REVIEW'
  ) THEN RAISE EXCEPTION 'candidate review guard failed'; END IF;
END
$guard$;

